   160  template <bool extended>
   161  struct Format1Entry;
   162
   163  template <>
   164  struct Format1Entry<true>
   165  {
   166    enum Flags
   167    {
   168      Push                = 0x8000,       /* If set, push this glyph on the kerning stack. */
   169      DontAdvance         = 0x4000,       /* If set, don't advance to the next glyph
   170                                           * before going to the new state. */
   171      Reset               = 0x2000,       /* If set, reset the kerning data (clear the stack) */
   172      Reserved            = 0x1FFF,       /* Not used; set to 0. */
   173    };
   174
   175    struct EntryData
   176    {
   177      HBUINT16    kernActionIndex;/* Index into the kerning value array. If
   178                                   * this index is 0xFFFF, then no kerning
   179                                   * is to be performed. */
   180      public:
   181      DEFINE_SIZE_STATIC (2);
   182    };
   183
   184    static inline bool performAction (const Entry<EntryData> *entry)
   185    { return entry->data.kernActionIndex != 0xFFFF; }
